width = len(demo_input[0])

# Find connected components again
def find_components(grid, H, W):
    visited = [[False] * W for _ in range(H)]
    components = []

    for r in range(H):
        for c in range(W):
            if grid[r][c] == fg and not visited[r][c]:
                component = []
                queue = [(r, c)]
                visited[r][c] = True

                while queue:
                    cr, cc = queue.pop(0)
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < H and 0 <= nc < W:
                            if grid[nr][nc] == fg and not visited[nr][nc]:
                                visited[nr][nc] = True
                                component.append((nr, nc))
                                queue.append((nr, nc))
                components.append(component)
    return components

components = find_components(demo_input, height, width)

# Which rows belong to which components?
comp_rows = {}
for c in range(len(components)):
    rows = sorted([r for r, c in components[c]])
    comp_rows[c] = set(rows)

print("Component rows:")
for c, rows in comp_rows.items():
